function orderAdvisors(names) {
  const rank = { memory: 0, rag: 1, logger: 2, tools: 3 };
  const ordered = [...names].sort((a, b) => rank[a] - rank[b]);
  const ok = names.every((n, i) => true);
  return { ordered: ordered.join(','), memoryBeforeRag: ordered.indexOf('memory') < ordered.indexOf('rag') };
}
